// One plan = everything a person approves at once: bookings, costs, date change, driver notice, buyer and delivery-contact drafts.
// Every price and time below comes from a fresh search or the dataset, never from the agent's own numbers.
// Modes: 'sub' = helper draft returned to the calling agent; run_id set = a problem workflow's draft, saved for the coordinator;
// 'preview' = the coordinator's full build without filing (for the message writer); 'file' (or none) = file the plan.
// @include travel.js
// @include plan.js
const KINDS = ['book_ferry', 'book_hotel', 'book_train', 'book_flight', 'approve_cost', 'change_delivery_window', 'cancel_delivery', 'reassign_driver', 'notify_driver', 'customer_message', 'delivery_contact_message', 'buyer_decision', 'staff_task'];
const ORDER = Object.fromEntries(KINDS.map((k, n) => [k, n])); // execution order: bookings first, people last
const i = $('Start').first().json;
const c = $('Get context').first().json;
const r = $json; // fresh ferry search (plan_rebooking); only used by a book_ferry line
const mode = String(i.mode || '').trim(), run = String(i.run_id || '').trim();
const helper = mode === 'sub', store = !helper && run && !['preview', 'file'].includes(mode), filing = !helper && !store && mode !== 'preview';
const fail = (error) => [{ json: { ok: false, error: 'NOT CREATED: ' + error } }];
if (!c.found) return fail(c.error);
let lines;
try { lines = typeof i.lines === 'string' ? JSON.parse(i.lines || '[]') : i.lines; } catch (e) { return fail('lines must be a JSON array of plan lines'); }
if (!Array.isArray(lines) || !lines.length) return fail('lines must be a non-empty JSON array of plan lines');
const S = c.settings, s = c.snapshot, now = Date.parse(s.snapshot_now), H = 36e5;
const zone = s.delivery?.timezone || 'UTC';
const EUR_PER = { EUR: 1, ...Object.fromEntries(String(S.currency_per_eur || '').split(',').map((x) => x.trim().split(/\s+/)).filter(([c, r]) => c && Number(r) > 0).map(([c, r]) => [c.toUpperCase(), 1 / Number(r)])) }; // rates from the Settings page; a currency not listed goes to a person
const eur = (cents) => Math.round(cents) / 100;
const text = (v) => String(v || '').trim();
const failedTravel = (c.plan_steps || []).filter((p) => ['book_train', 'book_flight'].includes(p.kind) && p.status === 'failed').map((p) => p.ref);
const win = (s.time_windows || []).find((w) => w.purpose === 'CUSTOMER_DELIVERY_PROMISE');
const winLen = win ? Math.max(2 * H, Date.parse(win.end_at) - Date.parse(win.start_at)) : 2 * H;
const steps = [], problems = [], valid = [];
let ferry = null, main = null, customer = text(i.customer_message), contact = text(i.delivery_contact_message), notes = [];
for (const [k, l] of lines.entries()) {
  const kind = text(l.kind), tag = `line ${k + 1} (${kind || 'no kind'})`;
  const bad = (m) => problems.push(`${tag}: ${m}`);
  if (kind === 'book_recovery') { bad("recovery, tow and repair are an employee task: call create_employee_task (normal) to get the price and ready time; the price comes back as an approve_cost line in the next plan"); continue; }
  if (!KINDS.includes(kind)) { bad(`kind must be one of ${KINDS.join(', ')}`); continue; }
  const before = steps.length;
  if (kind === 'book_ferry') {
    const o = !ferry && r.ok && (r.options || []).find((x) => x.option_id === text(l.option_id));
    if (ferry) { bad('only one ferry per plan'); continue; }
    if (!o) { bad(`option_id '${text(l.option_id)}' is not a usable ferry now; usable: ${(r.options || []).map((x) => x.option_id).join(', ') || 'none'} (call plan_rebooking)`); continue; }
    ferry = o;
    steps.push(...ferrySteps(o));
  } else if (kind === 'book_train' || kind === 'book_flight') {
    const earliest = Math.max(l.earliest ? Date.parse(l.earliest) : now, now + S.approval_buffer_min * 6e4 + S.booking_slack_min * 6e4);
    const t = searchTravel({ quotes: s.travel_options || [], from: l.from_city, to: l.to_city, earliest, failed: failedTravel });
    const o = t.ok && t.options.find((x) => x.option_id === text(l.option_id));
    if (!o) { bad(`option_id '${text(l.option_id)}' is not a usable option ${l.from_city} -> ${l.to_city} now${t.ok ? '; usable: ' + t.options.slice(0, 4).map((x) => x.option_id).join(', ') : ': ' + t.error} (call plan_driver_travel)`); continue; }
    if (o.mode !== (kind === 'book_train' ? 'TRAIN' : 'FLIGHT')) { bad(`option ${o.option_id} is a ${o.mode}; use book_${o.mode.toLowerCase()}`); continue; }
    const who = text(l.who) || (l.purpose === 'driver_return' ? 'current driver going home' : 'replacement driver');
    const step = travelStep(o, who, l.earliest);
    steps.push(step);
    // The replacement's trip decides the delivery date, so it is the one the buyer can choose between.
    if (!main && l.purpose !== 'driver_return') main = { step, o, search: t, who, earliest: l.earliest };
  } else if (kind === 'book_hotel') {
    const nights = Math.round(Number(l.nights) || 0), city = cityKey(l.city);
    if (!cityOf(city) || nights < 1 || nights > S.max_hotel_nights) { bad(`needs a known city and nights 1-${S.max_hotel_nights}`); continue; }
    const per = HOTEL_NIGHT_CENTS[city] || S.hotel_default_eur * 100;
    steps.push({ kind, detail: `${nights} night(s) ${city}${text(l.detail) ? ': ' + text(l.detail) : ''} (${HOTEL_NIGHT_CENTS[city] ? 'dataset hotel fare' : 'MOCK flat estimate'})`, cost_cents: nights * per });
  } else if (kind === 'approve_cost') {
    if (text(l.expense_id)) {
      const e = (s.expenses || []).find((x) => x.id === text(l.expense_id));
      if (!e) { bad(`no expense ${text(l.expense_id)} on this order`); continue; }
      if (e.status !== 'SUBMITTED') { bad(`expense ${e.id} is ${e.status}, only SUBMITTED claims can be approved`); continue; }
      const cur = e.currency || 'EUR', rate = EUR_PER[cur];
      if (!rate) { bad(`expense ${e.id} is in ${cur}; no exchange rate for it, ask a person`); continue; }
      const cents = Math.round(e.amount_cents * rate);
      steps.push({ kind, detail: `Driver expense ${e.kind} ${cur === 'EUR' ? '' : `${cur} ${eur(e.amount_cents)} = about `}EUR ${eur(cents)}, ${e.receipt_count} receipt(s)${e.receipt_count ? '' : ' (NO RECEIPT)'}, ${e.reimbursable_to_driver ? 'reimbursable to driver' : 'not marked reimbursable'}${text(l.detail) ? ': ' + text(l.detail) : ''}`, cost_cents: cents, ref: e.id });
    } else {
      const amt = Math.round(Number(l.amount_eur) * 100);
      if (!(amt > 0) || !text(l.detail)) { bad('needs expense_id, or amount_eur > 0 with a detail citing where the amount comes from (e.g. the employee\'s recovery price)'); continue; }
      // Booking prices are added by code from the search; an amount line is only for a price a person gave (recovery, repair).
      if (!/task #\d+/i.test(text(l.detail))) { bad('approve_cost with an amount is only for a price an employee gave in a task: cite "task #<id>". Ferry, train, flight and hotel prices are added by code; do not add them again'); continue; }
      steps.push({ kind, detail: `${text(l.detail)} (amount from evidence, check it)`, cost_cents: amt });
    }
  } else if (kind === 'change_delivery_window') {
    const a = Date.parse(l.start_at), b = Date.parse(l.end_at);
    if (Number.isNaN(a) || Number.isNaN(b) || a >= b || a < now) { bad('needs ISO start_at < end_at, after now (use check_journey suggested_new_window)'); continue; }
    steps.push(windowStep(a, b));
  } else if (kind === 'reassign_driver') {
    if (!text(l.driver_id) || !text(l.detail)) { bad('needs driver_id (from plan_driver_travel candidates) and detail'); continue; }
    steps.push({ kind, detail: `Hand the car to ${text(l.driver_id)}: ${text(l.detail)}`, cost_cents: 0, ref: text(l.driver_id) });
  } else if (kind === 'customer_message') {
    if (!text(l.detail)) { bad('detail must be the exact draft text'); continue; }
    customer = customer || text(l.detail);
  } else if (kind === 'delivery_contact_message') {
    if (!text(l.detail)) { bad('detail must be the exact draft text for the delivery contact'); continue; }
    contact = contact || text(l.detail);
  } else {
    if (!text(l.detail)) { bad('detail is required'); continue; }
    if (kind === 'notify_driver') notes.push(text(l.detail));
    else steps.push({ kind, detail: text(l.detail), cost_cents: 0, ...(kind === 'staff_task' && l.before_booking === true ? { before_booking: true } : {}) });
  }
  if (steps.length > before || ['customer_message', 'delivery_contact_message', 'notify_driver'].includes(kind)) valid.push(l);
}
if (problems.length) return fail(problems.join('; '));
const evidence = text(i.evidence_refs);
if (!evidence && !helper) return fail('evidence_refs is required');

// A workflow's draft: checked, then kept for the coordinator, which files one plan for every workflow on this event.
if (store) return [{ json: { ok: true, saved: true, row: { order_ref: c.order_ref, actor: 'agent', kind: 'plan_draft', source_ref: `run:${run}`,
  text: JSON.stringify({ workflow: run.split(':')[1] || '', lines: valid, customer_message: customer, delivery_contact_message: contact, rationale: text(i.rationale), evidence_refs: evidence, ready_at: text(i.ready_at) }) },
  note: 'Draft saved. When every workflow on this event is done, the coordinator files ONE plan with all drafts and one buyer message; a person approves it. Report what you found and stop.' } }];

// Options: when the main transport decides the date or the cost, the buyer may choose fastest, cheapest or balanced.
const agentWindow = steps.find((x) => x.kind === 'change_delivery_window');
let options = [];
if (ferry) {
  options = pickOptions((r.options || []).map((o) => ({ id: o.option_id, arrive_ms: Date.parse(o.ready_to_deliver), cost_cents: Math.round(o.total_eur * 100), late_h: o.late_hours, o })), S.eur_per_late_hour)
    .map((x) => ({ ...x, steps: [...ferrySteps(x.o), ...(x.o.late_hours > 0 ? [windowStep(Math.ceil(x.arrive_ms / H) * H, Math.ceil(x.arrive_ms / H) * H + winLen)] : [])],
      latest_bookable: Date.parse(x.o.cutoff) - (x.o.road_hours || 0) * H - S.booking_slack_min * 6e4, on_time: x.o.on_time }));
} else if (main && main.search.ok) {
  const first = Math.min(...main.search.options.map((o) => Date.parse(o.arrives)));
  const chosenAt = Date.parse(main.o.arrives);
  options = pickOptions(main.search.options.map((o) => ({ id: o.option_id, arrive_ms: Date.parse(o.arrives), cost_cents: o.cost_cents, late_h: (Date.parse(o.arrives) - first) / H, o })), S.eur_per_late_hour)
    .map((x) => {
      const shift = x.arrive_ms - chosenAt, w = agentWindow && shift > 0 ? [windowStep(agentWindow.start_ms + shift, agentWindow.end_ms + shift)] : agentWindow ? [agentWindow] : [];
      return { ...x, steps: [{ ...travelStep(x.o, main.who, main.earliest), kind: 'book_' + x.o.mode.toLowerCase() }, ...w], latest_bookable: Date.parse(x.o.leave_at || x.o.departs) - S.booking_slack_min * 6e4, on_time: null };
    });
}
// One real choice: no options, but a late ferry still carries its new delivery window.
if (options.length === 1 && !agentWindow) steps.push(...options[0].steps.filter((x) => x.kind === 'change_delivery_window'));
if (options.length < 2) options = [];
const optionKinds = (st) => ferry ? /^(book_ferry|book_hotel|change_delivery_window)$/.test(st.kind) && (st.kind !== 'book_hotel' || st.from_ferry) : st === main.step || st === agentWindow;
const common = options.length ? steps.filter((x) => !optionKinds(x)) : steps;

// A plan that only asks the buyer something holds no driver instruction: the driver hears the outcome after the buyer answers.
const questionOnly = !steps.some((x) => /^(book_|change_delivery_window|reassign_driver|cancel_delivery)/.test(x.kind));
const facts = common.filter((x) => /^book_(ferry|train|flight|hotel)$/.test(x.kind)).map((x) => x.detail.replace(/ \[.*?\]$/, ''));
if (!(questionOnly && customer) && (facts.length || notes.length || options.length))
  common.push({ kind: 'notify_driver', detail: `${facts.length ? 'New plan: ' + facts.join('; ') + '.' : options.length ? 'New plan: the option the buyer chooses (booking details added when it is booked).' : ''}${notes.length ? ' ' + notes.join(' ') : ''}`.trim(), cost_cents: 0 });
const changesDate = steps.some((x) => x.kind === 'change_delivery_window') || options.some((o) => o.steps.some((x) => x.kind === 'change_delivery_window'));
const cancels = steps.some((x) => x.kind === 'cancel_delivery');
if (customer) common.push({ kind: 'customer_message', detail: customer, cost_cents: 0 });
if (contact) common.push({ kind: 'delivery_contact_message', detail: contact, cost_cents: 0 });
// Options that all arrive on time do not need the buyer: the employee picks one (or asks the buyer first) when approving.
// With options, code alone decides whether the buyer is asked (an agent's own buyer_decision line would contradict them).
if (options.length) for (let k = common.length - 1; k >= 0; k--) if (common[k].kind === 'buyer_decision') common.splice(k, 1);
if ((changesDate || cancels) && !common.some((x) => x.kind === 'buyer_decision'))
  common.push({ kind: 'buyer_decision', detail: options.length ? "The buyer picks one option (or declines)." : cancels ? 'The buyer agrees to the cancellation or asks for another way.' : "The buyer accepts the new delivery window or asks for another time.", cost_cents: 0 });
const needsBuyer = common.some((x) => x.kind === 'buyer_decision');
const dc = s.delivery_contact;
if (filing) {
  if (needsBuyer && !customer) problems.push('customer_message draft is required when the buyer must decide (a person approves and sends it)');
  if (changesDate && S.confirm_with_delivery_contact === 'on' && dc?.name && !contact) problems.push(`delivery_contact_message draft is required: the new time must be confirmed with ${dc.name} (${dc.role}) at the delivery place`);
}
if (problems.length) return fail(problems.join('; '));

// A check a person must finish before anything is booked comes first; it is filed as an open step and blocks approval.
common.sort((a, b) => (a.before_booking ? -1 : ORDER[a.kind]) - (b.before_booking ? -1 : ORDER[b.kind]));
const commonCents = common.reduce((t, x) => t + (x.cost_cents || 0), 0);
const shownOptions = options.map((o, k) => {
  const cents = commonCents + o.steps.reduce((t, x) => t + (x.cost_cents || 0), 0);
  return { key: String.fromCharCode(65 + k), names: o.names, option_id: o.id, steps: o.steps.map(clean), total_cents: cents, total_eur: eur(cents),
    arrives: isoMin(o.arrive_ms), arrives_local: localTime(o.arrive_ms, zone), late_hours: +o.late_h.toFixed(1), on_time: o.on_time };
});
const recommended = shownOptions.find((o) => o.names.includes('balanced'))?.key || '';
const until = needsBuyer ? validUntil(now, S.offer_valid_min, options.map((o) => o.latest_bookable)) : null;
const total = shownOptions.length ? shownOptions.find((o) => o.key === recommended).total_cents : commonCents;
const plan = { steps: common.map(clean), total_cents: total, total_eur: eur(total), ready_at: r.assumptions?.ready_at || '', needs_buyer: needsBuyer, buyer_zone: zone,
  options: shownOptions, recommended, valid_until: until ? isoMin(until) : '', valid_until_local: until ? localTime(until, zone) : '' };
if (ferry) Object.assign(plan, { option_id: ferry.option_id, source: ferry.source, ticket_cents: ferry.ticket_cents, on_time: ferry.on_time, late_hours: ferry.late_hours, buffer_hours: ferry.buffer_hours });
const LABEL = { book_ferry: 'ferry', book_hotel: 'hotel', book_train: 'train', book_flight: 'flight', approve_cost: 'cost', change_delivery_window: 'new delivery window', cancel_delivery: 'cancellation', reassign_driver: 'new driver', notify_driver: 'driver notice', customer_message: 'buyer draft', delivery_contact_message: 'delivery-contact draft', buyer_decision: "buyer's answer", staff_task: 'staff task' };
const summary = `Plan: ${[...new Set([...common, ...options.flatMap((o) => o.steps)].map((x) => LABEL[x.kind]))].join(' + ')}; ${shownOptions.length ? `${shownOptions.length} options for the buyer (${shownOptions.map((o) => `${o.key} ${o.names.join('/')} EUR ${o.total_eur}`).join(', ')})` : `total EUR ${plan.total_eur}`}${ferry && !shownOptions.length ? `; delivery ${ferry.on_time ? 'on time (' + ferry.buffer_hours + ' h buffer)' : ferry.late_hours + ' h late'}` : ''}${needsBuyer ? '; the buyer must answer' : ''}.`;
if (helper) return [{ json: { ok: true, draft: true, lines: valid, customer_message_draft: customer, preview: steps.map((x) => `${x.kind}: ${x.detail} (EUR ${eur(x.cost_cents)})`), total_eur: eur(steps.reduce((t, x) => t + (x.cost_cents || 0), 0)),
  note: 'DRAFT, not filed. You were called by another workflow: return these lines and the buyer draft in your reply; the caller puts them in its own draft.' } }];
if (!filing) return [{ json: { ok: true, preview: true, summary, plan, buyer: s.customer?.name || 'buyer', delivery_contact: dc || null, window_was: win ? `${localTime(Date.parse(win.start_at), zone)} -> ${localTime(Date.parse(win.end_at), zone)}` : '' } }];
return [{ json: { ok: true, order_ref: c.order_ref, summary, payload: JSON.stringify(plan), rationale: text(i.rationale), evidence_refs: evidence } }];

function ferrySteps(o) {
  const out = [{ kind: 'book_ferry', detail: `${o.provider} ${o.route}, departs ${o.departs}, check-in by ${o.cutoff}, arrives ${o.arrives} [${o.source}]`, cost_cents: o.ticket_cents, ref: o.option_id }];
  if (o.hotel_nights_origin) out.push({ kind: 'book_hotel', detail: `${o.hotel_nights_origin} night(s) ${o.hotel_city_origin} before check-in`, cost_cents: Math.round(o.hotel_origin_eur * 100), from_ferry: true });
  if (o.hotel_nights_dest) out.push({ kind: 'book_hotel', detail: `${o.hotel_nights_dest} night(s) ${o.hotel_city_dest} until the delivery window`, cost_cents: Math.round(o.hotel_dest_eur * 100), from_ferry: true });
  return out;
}
function travelStep(o, who, earliest) {
  return { kind: 'book_' + o.mode.toLowerCase(), detail: `${who}: ${o.mode} ${o.provider} ${o.from_city} -> ${o.to_city}, leave ${o.leave_at}, departs ${o.departs}, arrives ${o.arrives} [${o.source}]`, cost_cents: o.cost_cents, ref: o.option_id,
    search: { from_city: o.from_city, to_city: o.to_city, earliest: earliest || '' } };
}
function windowStep(a, b) {
  return { kind: 'change_delivery_window', detail: `New delivery window ${isoMin(a)} -> ${isoMin(b)} (buyer time ${localTime(a, zone)} -> ${localTime(b, zone)}; was ${win ? win.start_at + ' -> ' + win.end_at : 'none'}). Only after the buyer agrees.`, cost_cents: 0, start_ms: a, end_ms: b };
}
function clean(x) { const { start_ms, end_ms, from_ferry, ...rest } = x; return rest; }
